mapper.select:
SELECT r.tenant_id,r.instance_id,r.installation_revision,r.definition_version_id,r.config,r.custom_prompt, v.id AS bound_definition_version_id,v.capability_version_id, (v.definition IS NOT NULL AND jsonb_typeof(v.definition) != 'null') AS definition_present, c.id AS container_id,c.workflow_id FROM nw_workflow_installation_revisions r LEFT JOIN nw_workflow_definition_versions anchor ON anchor.tenant_id=r.tenant_id AND anchor.id=r.definition_version_id LEFT JOIN nw_workflow_containers c ON c.tenant_id=anchor.tenant_id AND c.id=anchor.container_id LEFT JOIN nw_workflow_definition_versions v ON v.tenant_id=c.tenant_id AND v.container_id=c.id AND v.id=c.active_definition_version_id WHERE r.tenant_id=#{tenant}
AND (r.instance_id=#{identity.instanceId} AND r.installation_revision=#{identity.revision})
AND FALSE
